/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-watchdog> - quiet is not calm.
 *
 * For industrial, terminal, aegis and machina. The path a screen depends on,
 * drawn as a pipeline: one ring per stage, in path order, joined by a conduit
 * down to the elements it guards. Each ring fills toward its stage's late
 * threshold and carries its counter; each beat that ADVANCED the counter sends
 * a pulse down the conduit; each stage has a trace of its recent beats, a tall
 * spike where the counter moved and a short tick where it did not.
 *
 *   <ov-watchdog label="ALARM PATH" guards="cw"
 *                stages="FIELD SCAN:2, FRONT END:1, ALARM PROC:2"></ov-watchdog>
 *   wd.beat('ALARM PROC', 1042);                  // a beat, with its counter
 *   wd.beat('FRONT END', 88, { feed: 'scada' });  // and the feed it came by
 *
 *   <ov-watchdog source="relay" stages="RELAY:1"></ov-watchdog>
 *   // a source emits { stage, seq } or a list of them
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 AN EMPTY ALARM LIST IS NOT "NO ALARMS" UNLESS THE PATH IS PROVEN LIVE.
 * In August 2003 FirstEnergy's alarm list was quiet because the alarm
 * processor had stalled, and the operators "did not realize that alarm
 * processing on their EMS was not working and, subsequently, did not monitor
 * other available telemetry" (U.S.-Canada Blackout Final Report, p. 56). So
 * while any stage of the path is not proven, a guarded element that is quiet
 * reads UNPROVEN QUIET, naming the stage and since when; one that is showing
 * alerts reads PATH NOT PROVEN, because the next alert may not arrive. NERC
 * TOP-010-1(i) R4 requires an "alarm process monitor", and says it "must not
 * fail with a simultaneous failure" of what it watches.
 *
 * Three more that fall out of it:
 *
 * 1. RUNNING IS NOT WORKING. A beat proves a stage alive only if its counter
 *    ADVANCED. A fresh beat with the same counter is STALLED however fresh
 *    ("although the server and its applications were again running, the
 *    alarm system remained frozen and non-functional", p. 54): its trace goes
 *    flat, the way the 2003 chart pens "flat-lined" and nobody noticed. A
 *    beat with no counter at all is NO COUNTER: it proves running, never
 *    working. A counter that goes BACKWARDS is a restart, shown and counted.
 * 2. A MONITOR MAY NOT VOUCH FOR ITS OWN FEED. A beat that came by the same
 *    feed as an element it guards (the beat's `feed`, or this element's
 *    `source`, equals the guarded element's `source`) is NOT INDEPENDENT:
 *    when that feed stalls both go quiet together, which is exactly TOP-010's
 *    simultaneous failure.
 * 3. THE PAGE IS THE LAST STAGE, AND IT CANNOT PROVE ITSELF. Its own row
 *    steps a hand once a second on the main thread and traces its own ticks,
 *    so a frozen page is SEEN frozen. It is kept out of the verdict, because
 *    a page that is not drawing cannot draw that fact; what it can do is say
 *    afterwards that it did not draw, and for how long.
 *
 * A stage with no period is refused, not defaulted: a beat nobody expected
 * at any particular time can never be late.
 *
 * ⚠️ THE PAGE ROW COUNTS WHETHER OR NOT THE ELEMENT IS ON SCREEN. Redrawing
 * waits while the element is scrolled away, like every instrument in the kit,
 * but the tick that measures the page does not: skipping it would read as a
 * page that stopped drawing the moment someone scrolled back.
 *
 * Drawn at most once a second while on screen, and on each beat. The only
 * motion between draws is a pulse's short run down the conduit, skipped under
 * reduced motion; nothing here asks for an animation frame.
 *
 * INFERRED, not stated by any source: the late threshold (`grace` periods,
 * default 2), the advancing-counter test and NOT INDEPENDENT.
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';

const GRACE_DEFAULT = 2;
// How long a restart and a page gap stay on screen after they happen.
const NOTE_MS = 300_000;
// Each stage's trace shows its last TRACE_PERIODS periods, so a slow stage
// and a fast one draw at the same density.
const TRACE_PERIODS = 12;
const HIST = 120;

const WORD = {
  none: 'NO BEAT',
  live: 'LIVE',
  late: 'LATE',
  stalled: 'STALLED',
  uncounted: 'NO COUNTER',
  shared: 'NOT INDEPENDENT',
};

/* Seconds -> "12s", "14m 02s", "3h 05m", "2d 04h" (ov-downlink's span). */
export function span(s) {
  const n = Math.floor(s);
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m ${String(n % 60).padStart(2, '0')}s`;
  if (n < 86400) return `${Math.floor(n / 3600)}h ${String(Math.floor(n / 60) % 60).padStart(2, '0')}m`;
  return `${Math.floor(n / 86400)}d ${String(Math.floor(n / 3600) % 24).padStart(2, '0')}h`;
}

const every = (p) => (p < 1 ? `${Math.round(p * 1000)}ms` : span(p));
const clock = (ms) => new Date(ms).toTimeString().slice(0, 8);
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const f1 = (v) => v.toFixed(1);
// Writes only what changed: most of a panel is the same from one second to
// the next, and an unchanged attribute write is still a mutation.
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const reducedMotion = () => !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

let serial = 0;

/* A guarded element's banner: every watchdog's current claim, or none. */
function paintClaims(g) {
  const text = [...(g._ovUnproven?.values() ?? [])].join(' / ');
  if (!text) g.removeAttribute('data-ov-unproven');
  else if (g.getAttribute('data-ov-unproven') !== text) g.setAttribute('data-ov-unproven', text);
}

class OvWatchdog extends HTMLElement {
  static observedAttributes = ['label', 'stages', 'guards', 'grace', 'source'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._beats = new Map();       // stage -> { at, seq, movedAt, feed, restarts, restartAt, hist }
    this._page = { seq: 0, at: null, gap: null, hist: [] };
    this._undeclared = new Set();
    this._malformed = 0;
    this._proven = null;           // null until first evaluated
    this._since = null;
    this._marked = new Set();      // guarded elements this watchdog has marked
    this._pulses = new Set();      // stages whose counter moved since the last draw
    this._rows = new Map();
    this._rowKey = null;
    this._timer = 0;
    this._vid = `ov-watchdog-${++serial}`;
    this._onAlert = () => this.render();
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.bindSource();
    this.render();
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE. ov-core holds every feed, frame and
    // timer until the first screenful has landed; whenArrived fires at once
    // on an element upgraded after arrival.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.render());
    // A trip changes whether a guarded panel is quiet; do not wait a second
    // to stop calling it quiet.
    document.addEventListener('ov:annunciate', this._onAlert);
  }

  /* The page's own row: once a second, on the main thread, on purpose (a
   * compositor animation would keep moving through a frozen page). */
  startTicking() {
    if (this._timer || !this.isConnected) return;
    this.tick();
    this._timer = setInterval(() => this.tick(), 1000);
  }

  disconnectedCallback() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    document.removeEventListener('ov:annunciate', this._onAlert);
    for (const g of [...this._marked]) this.unmark(g);
  }

  attributeChangedCallback() {
    if (this.isConnected) this.render();
  }

  build() {
    this._built = true;
    this.innerHTML = '<div class="ov-head">'
      + '<span class="ov-aside ov-head__name ov-watchdog__label"></span>'
      + '<span class="ov-aside ov-head__note ov-watchdog__rules"></span></div>'
      + '<div class="ov-state ov-state--bar ov-watchdog__verdict">'
      + '<span class="ov-state__word ov-watchdog__verdictword"></span>'
      + '<span class="ov-state__why ov-watchdog__since"></span></div>'
      + '<ol class="ov-watchdog__stages"></ol>'
      + '<div class="ov-watchdog__sink" hidden></div>'
      + `<ol class="ov-watchdog__pagerow">${this.rowShell('THIS PAGE', true)}</ol>`
      + '<div class="ov-watchdog__foot"></div>'
      + `<span class="ov-watchdog__desc" id="${this._vid}"></span>`
      + '<span class="ov-watchdog__say" aria-live="polite"></span>';
    this.$ = {
      label: this.querySelector('.ov-watchdog__label'),
      rules: this.querySelector('.ov-watchdog__rules'),
      verdict: this.querySelector('.ov-watchdog__verdict'),
      word: this.querySelector('.ov-watchdog__verdictword'),
      since: this.querySelector('.ov-watchdog__since'),
      stages: this.querySelector('.ov-watchdog__stages'),
      sink: this.querySelector('.ov-watchdog__sink'),
      foot: this.querySelector('.ov-watchdog__foot'),
      desc: this.querySelector('.ov-watchdog__desc'),
      say: this.querySelector('.ov-watchdog__say'),
    };
    this._pageRef = this.refsOf(this.querySelector('.ov-watchdog__pagerow > li'));
    this.setAttribute('role', 'group');
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    // A source repeats its reading every tick, and here that is right: a
    // repeated counter is exactly what a stalled stage looks like, fresh and
    // not moving. A null is silence; the beats stop and their age says so.
    this.unsub = window.Overscan.subscribe(name, (r) => {
      if (r === null || r === undefined) return;
      for (const b of Array.isArray(r) ? r : [r]) {
        if (b && typeof b.stage === 'string') this.beat(b.stage, b.seq, { feed: b.feed ?? name });
      }
    });
  }

  /* ---- the door ------------------------------------------------------- */

  /* One beat from one stage. `seq` is its counter; without one the beat
   * proves only that something is running. Returns false for a stage this
   * path was not declared with (counted and shown, never given a row). */
  beat(stage, seq, opts = {}) {
    const now = OvWatchdog.now();
    if (!this.stages().some((s) => s.name === stage)) {
      this._undeclared.add(String(stage));
      if (this.isConnected) this.render();
      return false;
    }
    const b = this._beats.get(stage)
      || { at: null, seq: null, movedAt: null, feed: null, restarts: 0, restartAt: null, hist: [] };
    const n = seq === undefined || seq === null || seq === '' ? NaN : Number(seq);
    let kind;
    b.at = now;
    b.feed = opts.feed ?? null;
    if (!Number.isFinite(n)) {
      b.seq = null;
      b.movedAt = null;
      kind = 'none';
    } else {
      kind = b.seq === null || n > b.seq ? 'moved' : n < b.seq ? 'restart' : 'held';
      if (kind === 'restart') { b.restarts += 1; b.restartAt = now; }
      if (kind !== 'held') b.movedAt = now;
      b.seq = n;
    }
    b.hist.push({ at: now, kind });
    if (b.hist.length > HIST) b.hist.splice(0, b.hist.length - HIST);
    if (kind === 'moved' || kind === 'restart') this._pulses.add(stage);
    this._beats.set(stage, b);
    if (this.isConnected) this.render();
    return true;
  }

  /* The page's own beat. A gap longer than `grace` seconds since the last one
   * means the page was not drawing, and anything it showed in that time was
   * not current: said afterwards, since it could not be said then. Counted
   * always; drawn only while the element is on screen. */
  tick() {
    const now = OvWatchdog.now();
    const p = this._page;
    if (p.at !== null && (now - p.at) / 1000 > this.grace()) {
      p.gap = { secs: (now - p.at) / 1000, until: now };
    }
    p.seq += 1;
    p.at = now;
    p.hist.push(now);
    if (p.hist.length > HIST) p.hist.splice(0, p.hist.length - HIST);
    if (isSeen(this)) this.render();
  }

  /* ---- what is true right now ----------------------------------------- */

  /* `NAME:seconds`, comma separated, in path order. No period, no stage. */
  stages() {
    const out = [];
    const seen = new Set();
    this._malformed = 0;
    for (const part of (this.getAttribute('stages') || '').split(',')) {
      const p = part.trim();
      if (!p) continue;
      const at = p.lastIndexOf(':');
      const name = at > 0 ? p.slice(0, at).trim() : '';
      const period = at > 0 ? Number(p.slice(at + 1)) : NaN;
      if (!name || !Number.isFinite(period) || period <= 0 || seen.has(name)) { this._malformed += 1; continue; }
      seen.add(name);
      out.push({ name, period });
    }
    return out;
  }

  grace() {
    const g = Number(this.getAttribute('grace'));
    return this.hasAttribute('grace') && Number.isFinite(g) && g >= 1 ? g : GRACE_DEFAULT;
  }

  guarded() {
    const root = this.getRootNode();
    const scope = typeof root.getElementById === 'function' ? root : document;
    return (this.getAttribute('guards') || '').split(/\s+/).filter(Boolean)
      .map((id) => scope.getElementById(id)).filter(Boolean);
  }

  evaluate(now) {
    const grace = this.grace();
    const guardedFeeds = new Set(this.guarded().map((g) => g.getAttribute('source')).filter(Boolean));
    const own = this.getAttribute('source');
    return this.stages().map((s) => {
      const b = this._beats.get(s.name);
      const limit = s.period * grace * 1000;
      const row = {
        name: s.name, period: s.period, state: 'none', age: null, seq: null, held: null,
        feed: null, restarts: b?.restarts ?? 0, restartAt: b?.restartAt ?? null,
      };
      if (!b || b.at === null) return row;
      row.age = (now - b.at) / 1000;
      row.seq = b.seq;
      row.feed = b.feed ?? own ?? null;
      // Shared first: however lively, a beat on the guarded element's own feed
      // cannot vouch for it. Then late before stalled: a stall is a FRESH beat
      // that did not move.
      if (row.feed && guardedFeeds.has(row.feed)) row.state = 'shared';
      else if (now - b.at > limit) row.state = 'late';
      else if (b.seq === null) row.state = 'uncounted';
      else if (false) { row.state = 'stalled'; }  // MUTANT: running counts as working
      else row.state = 'live';
      return row;
    });
  }

  /* Whether a guarded element is showing nothing. true, false, or null when
   * this cannot tell (and then it does not say "quiet" on its behalf). */
  quietOf(g) {
    if (typeof g.snapshot === 'function') {
      const s = g.snapshot();
      if (Array.isArray(s?.tiles) && s.tiles.length) {
        if (s.tiles.every((t) => t.state === 'normal')) return true;
        if (s.tiles.some((t) => ['alert', 'acked', 'latched'].includes(t.state))) return false;
      }
      return null;
    }
    const r = g.report;
    if (r && typeof r.kept === 'number') return r.kept === 0;
    return null;
  }

  get report() {
    const now = OvWatchdog.now();
    return {
      proven: this._proven,
      since: this._since,
      stages: this.evaluate(now),
      page: { seq: this._page.seq, gap: this._page.gap },
      undeclared: [...this._undeclared],
      malformed: this._malformed,
    };
  }

  labelText() { return this.getAttribute('label') || 'watchdog'; }

  whyOf(r, now) {
    if (r.state === 'none') return 'never beaten';
    if (r.state === 'late') return `expected every ${every(r.period)}, nothing for ${span(r.age)}`;
    if (r.state === 'stalled') return `beating, but its counter has held at #${r.seq} for ${span(r.held)}: running is not working`;
    if (r.state === 'uncounted') return 'its beats carry no counter: they prove running, not working';
    if (r.state === 'shared') return `came by ${r.feed}, the feed it guards: it cannot vouch for it`;
    if (r.restartAt !== null && now - r.restartAt < NOTE_MS) {
      return `counter went back: restarted ${span((now - r.restartAt) / 1000)} ago`;
    }
    return '';
  }

  /* ---- drawing -------------------------------------------------------- */

  render() {
    if (!this._built) return;
    const now = OvWatchdog.now();
    const rows = this.evaluate(now);
    const first = rows.find((r) => r.state !== 'live') || null;
    const proven = rows.length > 0 && !first;
    const why = first ? `${first.name} ${WORD[first.state]}` : rows.length ? '' : 'NO STAGES DECLARED';
    const whySay = first ? `${first.name} ${WORD[first.state].toLowerCase()}` : 'no stages declared';

    if (proven !== this._proven) {
      const previous = this._proven;
      this._proven = proven;
      this._since = proven ? null : now;
      if (previous !== null) {
        this.say(proven ? `${this.labelText()}: path proven live` : `${this.labelText()}: path not proven, ${whySay}`);
      }
      this.dispatchEvent(new CustomEvent('ov:watchdog', {
        bubbles: true, detail: { proven, previous, stage: first?.name ?? null, state: first?.state ?? null },
      }));
    }

    setText(this.$.label, this.getAttribute('label') || '');
    setText(this.$.rules, `LATE AFTER ${this.grace()} PERIODS`);
    setAttr(this, 'data-ov-path', proven ? 'live' : 'unproven');
    // ok: proven, and the rings already show it, so dense draws no box.
    // bad: the verdict is the refusal, and it is never chrome.
    setAttr(this.$.verdict, 'data-ov-tone', proven ? 'ok' : 'bad');
    setText(this.$.word, proven ? 'PATH LIVE' : 'NOT PROVEN');
    setText(this.$.since, proven ? ''
      : `${why} · SINCE ${clock(this._since)} (${span((now - this._since) / 1000)})`);

    this.ensureRows(rows);
    for (const r of rows) this.drawStage(this._rows.get(r.name), r, now);
    this.drawPage(now);
    this.firePulses();

    const foot = [];
    const gap = this._page.gap;
    if (gap && now - gap.until < NOTE_MS) {
      foot.push(`THIS PAGE DID NOT DRAW FOR ${span(gap.secs)}, UNTIL ${clock(gap.until)}: NOTHING SHOWN THEN WAS CURRENT`);
    }
    if (this._undeclared.size) {
      foot.push(`${this._undeclared.size} BEAT${this._undeclared.size > 1 ? 'S' : ''} FROM UNDECLARED STAGES: ${[...this._undeclared].join(', ')}`);
    }
    if (this._malformed) {
      foot.push(`${this._malformed} STAGE${this._malformed > 1 ? 'S' : ''} REFUSED: A STAGE NEEDS A NAME AND A PERIOD`);
    }
    setText(this.$.foot, foot.join(' · '));

    // The accessible name opens with the label, whatever the density shows.
    setAttr(this, 'aria-label', proven ? `${this.labelText()}, path proven live`
      : `${this.labelText()}, path not proven, ${whySay}, since ${clock(this._since)}`);
    setText(this.$.desc, proven ? ''
      : `${this.labelText()} not proven: ${whySay}, since ${clock(this._since)}. Silence here is not evidence.`);

    // The binding. Only elements this watchdog marked are ever unmarked, so
    // two watchdogs guarding one element do not clear each other.
    const guarded = this.guarded();
    const sink = [];
    for (const g of guarded) {
      const name = g.getAttribute('label') || g.id;
      if (!proven) {
        const text = this.bannerFor(g, why);
        this.mark(g, text);
        sink.push(`<span class="ov-watchdog__sinkitem">${esc(name)} · ${esc(text)}</span>`);
      } else {
        if (this._marked.has(g)) this.unmark(g);
        sink.push(`<span class="ov-watchdog__sinkitem">${esc(name)} · PATH PROVEN: ITS SILENCE IS EVIDENCE</span>`);
      }
    }
    for (const g of [...this._marked]) if (!guarded.includes(g)) this.unmark(g);
    const sinkHtml = sink.join('');
    if (sinkHtml !== this._sinkHtml) { this._sinkHtml = sinkHtml; this.$.sink.innerHTML = sinkHtml; }
    this.$.sink.hidden = !sink.length;
  }

  /* The rows are built once per set of stages and then only updated, so a
   * pulse in flight is not cut off by the next second's draw. */
  ensureRows(rows) {
    const key = rows.map((r) => r.name).join(' ');
    if (key === this._rowKey) return;
    this._rowKey = key;
    this.$.stages.innerHTML = rows.map((r) => this.rowShell(r.name, false)).join('');
    this._rows = new Map([...this.$.stages.children].map((li) => [li.dataset.ovStage, this.refsOf(li)]));
  }

  rowShell(name, page) {
    return `<li class="ov-watchdog__stage${page ? ' ov-watchdog__page' : ''}" data-ov-stage="${esc(name)}" data-ov-beat="${page ? 'page' : 'none'}">`
      + '<svg class="ov-watchdog__ring" viewBox="0 0 48 48" aria-hidden="true">'
      + '<circle class="ov-watchdog__ringtrack" cx="24" cy="24" r="18"/>'
      + (page
        ? '<path class="ov-watchdog__dial" d="M24 3v4M45 24h-4M24 45v-4M3 24h4"/><line class="ov-watchdog__hand" x1="24" y1="24" x2="24" y2="10"/>'
        : '<circle class="ov-watchdog__ringarc" cx="24" cy="24" r="18" pathLength="100" transform="rotate(-90 24 24)" stroke-dasharray="0 100"/>'
          + '<path class="ov-watchdog__ringmark" d=""/>'
          + '<text class="ov-watchdog__ringseq" x="24" y="27"></text>')
      + '</svg>'
      + '<div class="ov-watchdog__info"><div class="ov-watchdog__line">'
      + `<span class="ov-watchdog__name">${esc(name)}</span>`
      + '<span class="ov-aside ov-watchdog__period"></span><span class="ov-watchdog__age"></span>'
      + '<span class="ov-watchdog__word"></span></div>'
      + '<svg class="ov-watchdog__trace" viewBox="0 0 300 40" preserveAspectRatio="none" aria-hidden="true">'
      + '<rect class="ov-watchdog__missing" x="300" y="0" width="0" height="40"/>'
      + '<path class="ov-watchdog__base" d="M0 36H300"/>'
      + '<path class="ov-watchdog__flat" d=""/>'
      + '<path class="ov-watchdog__expected" d=""/>'
      + '<path class="ov-watchdog__held" d=""/>'
      + '<path class="ov-watchdog__none" d=""/>'
      + '<path class="ov-watchdog__moved" d=""/>'
      + '<path class="ov-watchdog__now" d="M299.5 2V40"/></svg>'
      + `<span class="${page ? 'ov-aside ' : ''}ov-watchdog__why"></span></div>`
      + (page ? '' : '<span class="ov-watchdog__conduit" aria-hidden="true"><i class="ov-watchdog__pulse"></i></span>')
      + '</li>';
  }

  refsOf(li) {
    const q = (c) => li.querySelector(`.ov-watchdog__${c}`);
    return {
      li, arc: q('ringarc'), mark: q('ringmark'), seq: q('ringseq'), hand: q('hand'),
      period: q('period'), age: q('age'), word: q('word'), why: q('why'),
      missing: q('missing'), flat: q('flat'), expected: q('expected'),
      held: q('held'), none: q('none'), moved: q('moved'), pulse: q('pulse'),
    };
  }

  drawStage(ref, r, now) {
    const b = this._beats.get(r.name);
    const P = r.period * 1000;
    const G = this.grace();
    setAttr(ref.li, 'data-ov-beat', r.state);

    // The ring fills toward the late threshold; its tick marks one period,
    // when the next beat is due. A stall fills with the time the counter has
    // held instead; late and shared are a full ring (drawn dashed by CSS).
    let frac = 0;
    if (b && b.at !== null) {
      if (r.state === 'live' || r.state === 'uncounted') frac = Math.min(1, (now - b.at) / (P * G));
      else if (r.state === 'stalled') frac = Math.min(1, (now - b.movedAt) / (P * G));
      else frac = 1;
    }
    setAttr(ref.arc, 'stroke-dasharray', `${f1(frac * 100)} 100`);
    const a = (2 * Math.PI) / G - Math.PI / 2;
    setAttr(ref.mark, 'd', `M${f1(24 + 14 * Math.cos(a))} ${f1(24 + 14 * Math.sin(a))}L${f1(24 + 22 * Math.cos(a))} ${f1(24 + 22 * Math.sin(a))}`);
    setText(ref.seq, r.seq !== null ? `#${r.seq}` : r.state === 'none' ? '' : 'NO #');

    setText(ref.period, `EVERY ${every(r.period)}`);
    setText(ref.age, r.age === null ? 'NEVER' : `−${span(r.age)}`);
    setText(ref.word, WORD[r.state]);
    setText(ref.why, this.whyOf(r, now));

    // The trace: its last TRACE_PERIODS periods, now at the right edge.
    const win = P * TRACE_PERIODS;
    const x = (t) => 300 - ((now - t) / win) * 300;
    const d = { moved: '', held: '', none: '' };
    for (const h of (b?.hist || [])) {
      if (now - h.at > win) continue;
      const xx = f1(x(h.at));
      if (h.kind === 'moved') d.moved += `M${xx} 36V4`;
      else if (h.kind === 'restart') d.moved += `M${xx} 36V14M${xx} 14h-6`;
      else if (h.kind === 'held') d.held += `M${xx} 36V30`;
      else d.none += `M${xx} 36V22`;
    }
    setAttr(ref.moved, 'd', d.moved);
    setAttr(ref.held, 'd', d.held);
    setAttr(ref.none, 'd', d.none);

    // Silence drawn as what it is: a shaded gap from the late threshold to
    // now, with a dashed tick wherever a beat was due and did not come.
    let missX = r.state === 'none' ? 0 : 300;
    let exp = '';
    if (b && b.at !== null && now - b.at > P * G) {
      missX = Math.max(0, x(b.at + P * G));
      for (let t = b.at + P; t <= now; t += P) if (now - t <= win) exp += `M${f1(x(t))} 36V14`;
    }
    setAttr(ref.missing, 'x', f1(missX));
    setAttr(ref.missing, 'width', f1(300 - missX));
    setAttr(ref.expected, 'd', exp);
    setAttr(ref.flat, 'd', r.state === 'stalled' ? `M${f1(Math.max(0, x(b.movedAt)))} 36H300` : '');
  }

  /* The page's own row: a hand stepping once a second and a trace of its
   * own ticks. Both are drawn by the thread they measure, which is the point:
   * if that thread stops, so do they. */
  drawPage(now) {
    const ref = this._pageRef;
    const p = this._page;
    setAttr(ref.hand, 'transform', `rotate(${(p.seq % 8) * 45} 24 24)`);
    setText(ref.period, 'EVERY 1s');
    setText(ref.age, `#${p.seq}`);
    setText(ref.word, 'DRAWING');
    setText(ref.why, 'counted on this page\'s own thread: if it stops, so did the page');
    const win = 1000 * TRACE_PERIODS;
    const x = (t) => 300 - ((now - t) / win) * 300;
    setAttr(ref.moved, 'd', p.hist.filter((t) => now - t <= win).map((t) => `M${f1(x(t))} 36V10`).join(''));
    let missX = 300;
    let missW = 0;
    if (p.gap && now - p.gap.until <= win) {
      missX = Math.max(0, x(p.gap.until - p.gap.secs * 1000));
      missW = x(p.gap.until) - missX;
    }
    setAttr(ref.missing, 'x', f1(missX));
    setAttr(ref.missing, 'width', f1(Math.max(0, missW)));
  }

  /* A pulse runs down the conduit from each stage whose counter moved. A
   * held or uncounted beat sends nothing: it did not carry work downstream. */
  firePulses() {
    if (!this._pulses.size) return;
    const names = [...this._pulses];
    this._pulses.clear();
    if (reducedMotion()) return;
    for (const name of names) {
      const pulse = this._rows.get(name)?.pulse;
      if (pulse?.animate) {
        pulse.animate([{ top: '0%', opacity: 1 }, { top: '100%', opacity: 0.15 }],
          { duration: 650, easing: 'cubic-bezier(.4,0,.8,.6)' });
      }
    }
  }

  bannerFor(g, why) {
    const quiet = this.quietOf(g);
    const since = `SINCE ${clock(this._since)}`;
    if (quiet === true) return `UNPROVEN QUIET · ${why} · ${since}`;
    if (quiet === false) return `PATH NOT PROVEN · NEW ALERTS MAY NOT ARRIVE · ${why}`;
    return `PATH NOT PROVEN · ${why} · ${since}`;
  }

  /* 🔴 ONE ATTRIBUTE, SEVERAL CLAIMS. Two watchdogs can guard one element
   * (an alarm path and a comms path), and the first cut kept a single
   * attribute, so the one that proved its path erased the other's warning.
   * Each watchdog now keeps its own claim on the element, and the attribute
   * is written from whatever claims remain. */
  mark(g, text) {
    (g._ovUnproven ||= new Map()).set(this._vid, text);
    paintClaims(g);
    const ids = (g.getAttribute('aria-describedby') || '').split(/\s+/).filter(Boolean);
    if (!ids.includes(this._vid)) g.setAttribute('aria-describedby', [...ids, this._vid].join(' '));
    this._marked.add(g);
  }

  unmark(g) {
    g._ovUnproven?.delete(this._vid);
    paintClaims(g);
    const ids = (g.getAttribute('aria-describedby') || '').split(/\s+/).filter((t) => t && t !== this._vid);
    if (ids.length) g.setAttribute('aria-describedby', ids.join(' '));
    else g.removeAttribute('aria-describedby');
    this._marked.delete(g);
  }

  /* Everything said in one task is joined and said once: several writes to a
   * live region in one task are heard as the last only. */
  say(text) {
    const region = this.$.say;
    (region._ovSay ||= []).push(text);
    if (region._ovSay.length > 1) return;
    queueMicrotask(() => {
      const all = region._ovSay;
      region._ovSay = [];
      region.textContent = '';
      region.textContent = all.join('. ');
    });
  }
}

define('ov-watchdog', OvWatchdog);

export { OvWatchdog };
